mapper.select:
SELECT c.category_num, c.category_name, c.category_emoji, c.parent_category_num, p.category_name AS parent_category_name, p.category_emoji AS parent_category_emoji, SUM(t.trans_amount) AS amount, c.category_type FROM personal_categories c JOIN personal_transactions t ON t.category_num = c.category_num LEFT JOIN personal_categories p ON c.parent_category_num = p.category_num WHERE t.user_num = #{userNum} AND t.use_yn = 'Y'
AND t.trans_date >= #{startDate} AND t.trans_date < #{endDate}
GROUP BY c.category_num ORDER BY amount DESC

SELECT DATE_FORMAT(trans_date, '%Y-%m') AS yearMonth,
		SUM(CASE WHEN trans_type = 'I' THEN trans_amount ELSE 0 END) AS totalIncome,
		SUM(CASE WHEN trans_type = 'E' THEN trans_amount ELSE 0 END) AS totalExpense
FROM personal_transactions
WHERE user_num = #{userNum}
  AND use_yn = 'Y'

  AND trans_date >= #{startDate}
  AND trans_date < #{endDate}

GROUP BY yearMonth
ORDER BY yearMonth
